<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Library Inventory | C-Net Library</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f5f7fb;color:#1f2937}.wrap{max-width:1450px;margin:26px auto;padding:0 18px}.top,.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:17px;margin-bottom:16px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#111827;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.green{background:#047857}.red{background:#b91c1c}.light{background:#fff;color:#111827;border:1px solid #d1d5db}.field{margin-bottom:10px}label{font-size:12px;font-weight:700;color:#475569}input,select,textarea{width:100%;padding:9px;border:1px solid #d1d5db;border-radius:8px;margin-top:4px}.muted{color:#6b7280;font-size:12px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1050px}th,td{padding:9px;border-bottom:1px solid #edf0f4;text-align:left;vertical-align:top;font-size:13px}th{background:#f8fafc}.editgrid{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:6px}.notice{padding:12px;border-radius:9px;margin-bottom:14px}.ok{background:#ecfdf5}.err{background:#fef2f2}@media(max-width:900px){.grid,.editgrid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Physical Library Inventory</h1><div class="muted">Categories, book masters, branch-wise copies, accession/barcode, rack and safe deletion.</div></div><div class="inline"><a class="btn light" href="{{ route('admin.library.index') }}">Circulation</a><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div></div>@if(session('success'))<div class="notice ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="notice err"><strong>Please correct:</strong><ul>@foreach($errors->all() as $e)<li>{{ $e }}</li>@endforeach</ul></div>@endif
