<div class="card"><div class="top"><div><h2 style="margin:0">Book Copies</h2><div class="muted">Issued/reserved status can only be changed through circulation workflow.</div></div><form class="inline" method="GET"><input name="q" value="{{ request('q') }}" placeholder="Search accession/barcode/book/rack"><select name="branch_id"><option value="">All branches</option>@foreach($branches as $br)<option value="{{ $br->id }}" @selected(request('branch_id')==$br->id)>{{ $br->name }}</option>@endforeach</select><button class="btn">Filter</button></form></div><div class="tablewrap"><table><thead><tr><th>Copy</th><th>History</th><th>Edit</th><th>Delete</th></tr></thead><tbody>@forelse($copies as $cp)<tr><td><strong>{{ $cp->book?->title }}</strong><br>{{ $cp->accession_no }} · {{ $cp->barcode ?: 'No barcode' }}<br><span class="muted">{{ $cp->branch?->name }} · Rack {{ $cp->rack_no ?: '—' }} · {{ $cp->status }}</span></td><td>Issues {{ $cp->issues_count }}<br>Reservations {{ $cp->reservations_count }}</td><td><form method="POST" action="{{ route('admin.library-inventory.copies.update',$cp) }}">@csrf @method('PATCH')<div class="editgrid"><select name="book_id">@foreach($books as $b)<option value="{{ $b->id }}" @selected($cp->book_id==$b->id)>{{ $b->title }}</option>@endforeach</select><select name="branch_id">@foreach($branches as $br)<option value="{{ $br->id }}" @selected($cp->branch_id==$br->id)>{{ $br->name }}</option>@endforeach</select><input name="accession_no" value="{{ $cp->accession_no }}" required><input name="barcode" value="{{ $cp->barcode }}" placeholder="Barcode"><input name="rack_no" value="{{ $cp->rack_no }}" placeholder="Rack"><select name="condition">@foreach(['new','good','fair','damaged'] as $v)<option value="{{ $v }}" @selected($cp->condition==$v)>{{ ucfirst($v) }}</option>@endforeach</select><select name="status">@foreach(['available','issued','reserved','lost','damaged'] as $v)<option value="{{ $v }}" @selected($cp->status==$v)>{{ ucfirst($v) }}</option>@endforeach</select></div><button class="btn green">Save Copy</button></form></td><td><form method="POST" action="{{ route('admin.library-inventory.copies.destroy',$cp) }}" onsubmit="return confirm('Delete this unused copy permanently?')">@csrf @method('DELETE')<button class="btn red">Delete</button></form></td></tr>@empty<tr><td colspan="4">No copies found.</td></tr>@endforelse</tbody></table></div><div style="margin-top:12px">{{ $copies->links() }}</div></div></div></body></html>